dtsPropsFor.Button:
/** `primary` = ink fill that turns accent on hover (default); `secondary` = outlined; `ghost` = text only, hover tint; `danger` = red fill for destructive confirms. */
variant?: "primary" | "secondary" | "ghost" | "danger";
/** `sm` = 13px text, `md` = 14px (default). */
size?: "sm" | "md";
children: React.ReactNode;
/** Defaults to "button": it only submits a form when set to "submit". */
type?: "button" | "submit" | "reset";
/** Dims to 50% and stops hover and clicks. */
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
title?: string;
"aria-label"?: string;
className?: string;
/** Merged last, over the pill's own padding, radius and font. */
style?: React.CSSProperties;
// Every other native <button> attribute passes through to the element.

dtsPropsFor.IconButton:
/** Required: the tooltip and the accessible name (aria-label). */
title: string;
/** The glyph: a character such as ✕ or ⋯, an emoji, or an inline SVG. */
children: React.ReactNode;
/** `sm` = 30px circle (default), `md` = 34px. */
size?: "sm" | "md";
/** Defaults to "button". */
type?: "button" | "submit" | "reset";
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
"aria-pressed"?: boolean;
"aria-expanded"?: boolean;
className?: string;
/** Merged last, over the circle's own size and colour. */
style?: React.CSSProperties;
// Every other native <button> attribute passes through to the element.

dtsPropsFor.Input:
value?: string | number;
defaultValue?: string | number;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
placeholder?: string;
/** Native input type; defaults to "text". */
type?: string;
name?: string;
id?: string;
disabled?: boolean;
readOnly?: boolean;
required?: boolean;
autoFocus?: boolean;
autoComplete?: string;
maxLength?: number;
onKeyDown?: React.KeyboardEventHandler<HTMLInputElement>;
onFocus?: React.FocusEventHandler<HTMLInputElement>;
onBlur?: React.FocusEventHandler<HTMLInputElement>;
"aria-label"?: string;
"aria-invalid"?: boolean;
className?: string;
/** Merged last, over the pill field: panel ground, 1.5px field-colour border that turns ink on focus, full width. */
style?: React.CSSProperties;
// Every other native <input> attribute passes through to the element.

dtsPropsFor.Textarea:
value?: string;
defaultValue?: string;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
placeholder?: string;
rows?: number;
name?: string;
id?: string;
disabled?: boolean;
readOnly?: boolean;
required?: boolean;
