dtsPropsFor.Menu:
/** The element that opens the menu, usually a Button or IconButton. Menu clones it to add the click handler and aria-haspopup/aria-expanded. */
trigger: React.ReactElement<{ onClick?: React.MouseEventHandler }>;
/** The options, in order. `onActivate` runs on a pick; `danger` colours a destructive one red; `checked` marks the current option (✓) when `selection` is set. */
items: Array<{ key: string; label: string; subtitle?: string; icon?: React.ReactNode; onActivate: () => void; danger?: boolean; disabled?: boolean; checked?: boolean }>;
/** Default "bottom-start". */
placement?: "bottom-start" | "bottom-end" | "top-start";
/** Show a filter input at the top that narrows items by label (case-insensitive). */
searchable?: boolean;
/** Default "Search…". */
searchPlaceholder?: string;
/** Stretch the trigger wrapper to fill its flex row (property editors on the issue page). */
fullWidth?: boolean;
/** Options with a current value: `single` closes on a pick, `multi` (several at once) stays open. Each item's `checked` is announced and marked with a ✓. */
selection?: "single" | "multi";
/** Merged over the popover's placement (e.g. to line it up with a column of the trigger). */
popoverStyle?: React.CSSProperties;
/** Merged over each item's type and spacing. */
itemStyle?: React.CSSProperties;
/** Place the popover against the nearest positioned ancestor instead of the trigger's wrapper: for a row that holds more than the trigger, so the popover spans the whole row. */
anchorToParent?: boolean;

dtsPropsFor.QueryState:
/** A react-query result (useQuery or useInfiniteQuery); only these fields are read. */
query: { isLoading: boolean; isError: boolean; data?: unknown; isPaused?: boolean; isFetching?: boolean; refetch: () => unknown };
/** Names what failed in the error card: "Couldn't load {what}." */
what: string;
/** Wraps the loading line and the error card, for a page whose content area has no padding of its own. */
frame?: React.CSSProperties;
/** The page's own content, shown once the query has data (it keeps its own empty state). */
children: React.ReactNode;

dtsPropsFor.AvatarStack:
/** One entry per person, in order; each renders as an Avatar (initials on `color`; no initials = dashed "Unassigned" ring). */
avatars: Array<{ initials?: string; color?: string; title?: string }>;
/** Avatar diameter in px. Default 24. */
size?: number;
/** Avatars shown before a "+N" chip. Default 4. */
max?: number;

dtsPropsFor.SegmentedControl:
/** The segments, left to right. */
options: Array<{ label: string; value: string }>;
/** The selected option's value. */
value: string;
onChange: (value: string) => void;
